import sys
def rc4(k,d):
    S=list(range(256));j=0
    for i in range(256):
        j=(j+S[i]+k[i%len(k)])&255;S[i],S[j]=S[j],S[i]
    o=bytearray();i=j=0
    for b in d:
        i=(i+1)&255;j=(j+S[i])&255;S[i],S[j]=S[j],S[i];o.append(b^S[(S[i]+S[j])&255])
    return bytes(o)
